// 解析监控脚本输出
const output = $input.first().json.stdout;

// 提取JSON报告
const jsonStart = output.indexOf('JSON_REPORT_START');
const jsonEnd = output.indexOf('JSON_REPORT_END');

if (jsonStart === -1 || jsonEnd === -1) {
  throw new Error('无法找到JSON报告');
}

const jsonText = output.substring(
  jsonStart + 'JSON_REPORT_START'.length,
  jsonEnd
).trim();

const report = JSON.parse(jsonText);

return { json: report };

// 构建飞书卡片
const report = $input.first().json;
const checkTime = new Date(report.check_time).toLocaleString('zh-CN');

// 标题颜色
let titleColor = 'grey';
let titleEmoji = 'ℹ️';

if (report.total_changes > 0) {
  if (report.new_videos > 0) {
    titleColor = 'red';
    titleEmoji = '🆕';
  } else {
    titleColor = 'blue';
    titleEmoji = '📈';
  }
}

// 构建元素
const elements = [];

// 概览
elements.push({
  tag: 'div',
  text: {
    tag: 'lark_md',
    content: `**监控时间**: ${checkTime}\n**总变化数**: ${report.total_changes}\n**新视频**: ${report.new_videos} | **数据变化**: ${report.data_changes}`
  }
});

elements.push({ tag: 'hr' });

// 详细变化
if (report.total_changes > 0) {
  // 按账号分组
  const changesByAccount = {};

  for (const change of report.changes) {
    const username = change.username;
    if (!changesByAccount[username]) {
      changesByAccount[username] = { new_videos: [], data_changes: [] };
    }

    if (change.type === 'new_video') {
      changesByAccount[username].new_videos.push(change);
    } else {
      changesByAccount[username].data_changes.push(change);
    }
  }

  // 为每个账号生成通知
  for (const [username, changes] of Object.entries(changesByAccount)) {
    elements.push({
      tag: 'div',
      text: {
        tag: 'lark_md',
        content: `**👤 账号**: @${username}`
      }
    });

    // 新视频
    if (changes.new_videos.length > 0) {
      for (let i = 0; i < Math.min(5, changes.new_videos.length); i++) {
        const video = changes.new_videos[i];
        const title = video.title.length > 80 ? video.title.substring(0, 80) + '...' : video.title;
        elements.push({
          tag: 'div',
          text: {
            tag: 'lark_md',
            content: `🆕 **新视频**: ${title}\n🔗 [查看视频](${video.video_url})`
          }
        });
      }

      if (changes.new_videos.length > 5) {
        elements.push({
          tag: 'div',
          text: {
            tag: 'lark_md',
            content: `_...还有 ${changes.new_videos.length - 5} 个新视频_`
          }
        });
      }
    }

    // 数据变化
    if (changes.data_changes.length > 0) {
      for (let i = 0; i < Math.min(5, changes.data_changes.length); i++) {
        const video = changes.data_changes[i];
        const title = video.title.length > 80 ? video.title.substring(0, 80) + '...' : video.title;
        const changeText = video.changes.join('\n  • ');
        elements.push({
          tag: 'div',
          text: {
            tag: 'lark_md',
            content: `📈 **数据变化**: ${title}\n  • ${changeText}\n🔗 [查看视频](${video.video_url})`
          }
        });
      }

      if (changes.data_changes.length > 5) {
        elements.push({
          tag: 'div',
          text: {
            tag: 'lark_md',
            content: `_...还有 ${changes.data_changes.length - 5} 个视频有数据变化_`
          }
        });
      }
    }

    elements.push({ tag: 'hr' });
  }
} else {
  elements.push({
    tag: 'div',
    text: {
      tag: 'lark_md',
      content: '✅ 所有监控账号暂无变化'
    }
  });
}

// 构建完整卡片
const card = {
  header: {
    title: {
      tag: 'plain_text',
      content: `${titleEmoji} TikTok 账号监控报告`
    },
    template: titleColor
  },
  elements: elements
};

return {
  json: {
    ...report,
    feishu_card: card
  }
};

// 读取配置文件
const fs = require('fs');
const configPath = '/Users/nati/n8n-compose/tiktok_accounts.json';
const config = JSON.parse(fs.readFileSync(configPath, 'utf8'));

const report = $input.first().json;

return {
  json: {
    ...report,
    notification_config: config.config.notification,
    feishu_webhook: config.config.notification.feishu_webhook,
    bark_url: config.config.notification.bark_url
  }
};
